package gate

import (
	"encoding/json"
	"os"
	"testing"
	"time"

	"dnshived/internal/arbiter"
)

// The shared vectors (tests/relay/token-vectors.json) are generated by internal/arbiter and checked by
// tests/relay/check_token_vectors.py. The relay side is checked here against the same file.
type vectorFile struct {
	PSK     string `json:"psk"`
	Now     string `json:"now"`
	Vectors []struct {
		Name   string        `json:"name"`
		Token  arbiter.Token `json:"token"`
		Valid  bool          `json:"valid"`
		Reason string        `json:"reason"`
	} `json:"vectors"`
	Quorum []struct {
		Name     string   `json:"name"`
		Arbiters []string `json:"arbiters"`
		Expect   int      `json:"expect"`
	} `json:"quorum"`
}

func loadVectors(t *testing.T) (vectorFile, time.Time) {
	t.Helper()
	raw, err := os.ReadFile("../../tests/relay/token-vectors.json")
	if err != nil {
		t.Fatal(err)
	}
	var f vectorFile
	if err := json.Unmarshal(raw, &f); err != nil {
		t.Fatal(err)
	}
	now, err := time.Parse(time.RFC3339, f.Now)
	if err != nil {
		t.Fatal(err)
	}
	return f, now
}

// The vectors are issued for scope "office", owner "core-1", incarnation 7.
func TestVectorsThroughVerify(t *testing.T) {
	f, now := loadVectors(t)
	for _, v := range f.Vectors {
		err := Verify(v.Token, []byte(f.PSK), "office", "core-1", 7, now)
		reason := ""
		if err != nil {
			reason = err.(*CheckError).Reason
		}
		if (err == nil) != v.Valid || reason != v.Reason {
			t.Errorf("%s: got valid=%v reason=%q, want valid=%v reason=%q", v.Name, err == nil, reason, v.Valid, v.Reason)
		}
	}
}

func TestOwnerScopeIncarnationChecks(t *testing.T) {
	f, now := loadVectors(t)
	var good arbiter.Token
	for _, v := range f.Vectors {
		if v.Name == "new_form_valid" {
			good = v.Token
		}
	}
	psk := []byte(f.PSK)
	cases := []struct {
		name, scope, owner string
		inc                uint64
		want               string
	}{
		{"scope", "dante-", "core-1", 7, "scope"},
		{"owner", "office", "core-2", 7, "owner"},
		{"incarnation", "office", "core-1", 8, "incarnation"},
	}
	for _, c := range cases {
		err := Verify(good, psk, c.scope, c.owner, c.inc, now)
		if err == nil || err.(*CheckError).Reason != c.want {
			t.Errorf("%s: got %v, want reason %q", c.name, err, c.want)
		}
	}
}

func TestQuorumVectors(t *testing.T) {
	f, _ := loadVectors(t)
	for _, q := range f.Quorum {
		distinct := map[string]bool{}
		for _, a := range q.Arbiters {
			if a != "" {
				distinct[a] = true
			}
		}
		if len(distinct) != q.Expect {
			t.Errorf("%s: %d distinct, want %d", q.Name, len(distinct), q.Expect)
		}
	}
}

func TestAuthorizeCountsDistinctArbitersAndSetsDeadline(t *testing.T) {
	f, now := loadVectors(t)
	psk := []byte(f.PSK)
	mk := func(arb string, exp time.Time) arbiter.Token {
		tok := arbiter.Token{Scope: "office", Owner: "core-1", Incarnation: 7,
			GrantedAt: now.Add(-5 * time.Second), ExpiresAt: exp, Nonce: arb + exp.String(), Arbiter: arb}
		tok.Signature = tok.Sign(psk)
		return tok
	}
	early := now.Add(20 * time.Second)
	late := now.Add(40 * time.Second)

	// Majority of three cores is 2: two renewals from one arbiter count once and do not reach it.
	_, err := Authorize([]arbiter.Token{mk("a", early), mk("a", late)}, psk, "office", "core-1", 7, 2, 0, now)
	if err == nil || err.(*CheckError).Reason != "quorum" {
		t.Fatalf("one arbiter twice: got %v, want quorum", err)
	}

	res, err := Authorize([]arbiter.Token{mk("a", early), mk("b", late)}, psk, "office", "core-1", 7, 2, 0, now)
	if err != nil {
		t.Fatal(err)
	}
	if res.Arbiters != 2 || !res.Deadline.Equal(early.Add(-DeadlineMargin)) {
		t.Fatalf("got arbiters=%d deadline=%s, want 2 and %s", res.Arbiters, res.Deadline, early.Add(-DeadlineMargin))
	}

	res, err = Authorize([]arbiter.Token{mk("a", early)}, psk, "office", "core-1", 7, 3, 1, now)
	if err != nil || !res.Lowered {
		t.Fatalf("lowered quorum: got %v lowered=%v", err, res.Lowered)
	}

	if _, err := Authorize([]arbiter.Token{mk("", early)}, psk, "office", "core-1", 7, 1, 0, now); err == nil {
		t.Fatal("old-form token (no arbiter) counted towards quorum")
	}
}

func TestRequiredQuorumNeverBelowOneNeverRaised(t *testing.T) {
	if n, _, _ := RequiredQuorum(3, 9); n != 3 {
		t.Errorf("raised to %d", n)
	}
	if _, _, err := RequiredQuorum(3, -1); err == nil {
		t.Error("negative request accepted")
	}
	if n, lowered, _ := RequiredQuorum(3, 1); n != 1 || !lowered {
		t.Errorf("lowering to 1: got %d lowered=%v", n, lowered)
	}
}
